void generateXBM(gdImagePtr image, char* file_name, int fg, gdIOCtx* out) {
    int width = image->sx;
    int height = image->sy;
    int i, j;
    char* modified_file_name = (char*)malloc(strlen(file_name) + 1);
    strcpy(modified_file_name, file_name);

    for (i = 0; modified_file_name[i]; i++) {
        if (!isalnum(modified_file_name[i])) {
            modified_file_name[i] = '_';
        }
    }

    char header[256];
    snprintf(header, sizeof(header),
             "#define %s_width %d\n"
             "#define %s_height %d\n"
             "static unsigned char %s_bits[] = {\n  0x",
             modified_file_name, width, modified_file_name, height, modified_file_name);

    gdWrite(out, header, strlen(header));

    for (j = 0; j < height; j++) {
        unsigned char byte = 0;
        int bits = 0;

        for (i = 0; i < width; i++) {
            int color = gdImageGetPixel(image, i, j);
            int bit = (color == fg) ? 1 : 0;
            byte = (byte << 1) | bit;
            bits++;

            if (bits == 8) {
                if (i != (width - 1)) {
                    snprintf(header, sizeof(header), "0x%02X, ", byte);
                } else {
                    snprintf(header, sizeof(header), "0x%02X", byte);
                }
                gdWrite(out, header, strlen(header));
                byte = 0;
                bits = 0;
            }
        }

        if (bits > 0) {
            byte <<= (8 - bits);
            if (j != (height - 1) || (j == (height - 1) && width % 8 != 0)) {
                snprintf(header, sizeof(header), "0x%02X, ", byte);
            } else {
                snprintf(header, sizeof(header), "0x%02X", byte);
            }
            gdWrite(out, header, strlen(header));
        }
    }

    snprintf(header, sizeof(header), "\n};");
    gdWrite(out, header, strlen(header));

    free(modified_file_name);
}

