void gdImageXBM(gdImagePtr image, char* file_name, int fg, gdIOCtx* out)
{
    int width = image->sx;
    int height = image->sy;
    int y, x;
    char* outName;
    int len;
    int i;

    /* Generate a valid C identifier from the file name */
    len = strlen(file_name);
    outName = (char*)malloc(len + 1);
    if (!outName) {
        return;
    }

    for (i = 0; i < len; i++) {
        if (isalnum((unsigned char)file_name[i])) {
            outName[i] = file_name[i];
        } else {
            outName[i] = '_';
        }
    }
    outName[len] = '\0';

    /* Write the XBM header */
    gdPutChar(out, '#');
    gdPutChar(out, 'd');
    gdPutChar(out, 'e');
    gdPutChar(out, 'f');
    gdPutChar(out, 'i');
    gdPutChar(out, 'n');
    gdPutChar(out, 'e');
    gdPutChar(out, ' ');
    gdPutChars(out, outName, len);
    gdPutChar(out, ' ');
    gdPutChars(out, (unsigned char*)"WIDTH", 5);
    gdPutChar(out, ' ');
    {
        char buffer[16];
        sprintf(buffer, "%d", width);
        gdPutChars(out, (unsigned char*)buffer, strlen(buffer));
    }

    gdPutChar(out, '\n');
    gdPutChar(out, '#');
    gdPutChar(out, 'd');
    gdPutChar(out, 'e');
    gdPutChar(out, 'f');
    gdPutChar(out, 'i');
    gdPutChar(out, 'n');
    gdPutChar(out, 'e');
    gdPutChar(out, ' ');
    gdPutChars(out, outName, len);
    gdPutChar(out, ' ');
    gdPutChars(out, (unsigned char*)"HEIGHT", 6);
    gdPutChar(out, ' ');
    {
        char buffer[16];
        sprintf(buffer, "%d", height);
        gdPutChars(out, (unsigned char*)buffer, strlen(buffer));
    }

    gdPutChar(out, '\n');
    gdPutChar(out, 'c');
    gdPutChar(out, 'h');
    gdPutChar(out, 'a');
    gdPutChar(out, 'r');
    gdPutChar(out, ' ');
    gdPutChars(out, outName, len);
    gdPutChar(out, '_');
    gdPutChars(out, (unsigned char*)"bits[]", 6);
    gdPutChar(out, ' ');
    gdPutChar(out, '=');
    gdPutChar(out, ' ');
    gdPutChar(out, '{');
    gdPutChar(out, '\n');

    for (y = 0; y < height; y++) {
        unsigned char bits[(width + 7) / 8];
        int bitsPos;
        int pixel;

        for (x = 0; x < (width + 7) / 8; x++) {
            bits[x] = 0;
        }

        for (bitsPos = 0; bitsPos < width; bitsPos++) {
            pixel = gdImageGetPixel(image, bitsPos, y);
            if (pixel == fg) {
                bits[bitsPos / 8] |= (1 << (7 - (bitsPos % 8)));
            }
        }

        for (x = 0; x < (width + 7) / 8; x++) {
            char buffer[4];
            sprintf(buffer, "0x%02x", bits[x]);
            gdPutChars(out, (unsigned char*)buffer, 4);
            if (x < (width + 7) / 8 - 1) {
                gdPutChar(out, ',');
            }
            if (x % 8 == 7) {
                gdPutChar(out, '\n');
            } else {
                gdPutChar(out, ' ');
            }
        }
    }

    gdPutChar(out, '};');
    free(outName);
}

void generateXBM(gdImagePtr image, char* file_name, int fg, gdIOCtx* out)
{
    int width = gdImageSX(image);
    int height = gdImageSY(image);
    int i, j;
    int y;
    unsigned char* pixels;
    char* safe_name;
    int name_len;
    int name_pos;
    int c;
    int line;
    int bits;

    safe_name = (char*)malloc(strlen(file_name) + 1);
    if (!safe_name) {
        return;
    }

    name_len = 0;
    for (i = 0; file_name[i]; i++) {
        c = file_name[i];
        if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_') {
            safe_name[name_len++] = (char)c;
        } else {
            safe_name[name_len++] = '_';
        }
    }
    safe_name[name_len] = '\0';

    gdIOCtx_printf(out, "#define %s_width %d\n", safe_name, width);
    gdIOCtx_printf(out, "#define %s_height %d\n", safe_name, height);

    pixels = (unsigned char*)malloc(width * height / 8 + ((width * height % 8) ? 1 : 0));
    if (!pixels) {
        free(safe_name);
        return;
    }

    for (i = 0; i < width * height / 8 + ((width * height % 8) ? 1 : 0); i++) {
        pixels[i] = 0;
    }

    for (y = 0; y < height; y++) {
        for (i = 0; i < width; i++) {
            if (gdImageGetPixel(image, i, y) == fg) {
                j = (y * width + i) / 8;
                bits = (y * width + i) % 8;
                pixels[j] |= (1 << (7 - bits));
            }
        }
    }

    gdIOCtx_printf(out, "static char %s_bits[] = {\n  ", safe_name);
    for (i = 0; i < (width * height + 7) / 8; i++) {
        if (i && (i % 16 == 0)) {
            gdIOCtx_printf(out, "\n  ");
        }
        if (i) {
            gdIOCtx_printf(out, ", ");
        }
        gdIOCtx_printf(out, "0x%02X", pixels[i]);
    }
    gdIOCtx_printf(out, "\n};\n");

    free(safe_name);
    free(pixels);
}

